/**
 * gitpushbutton.js
 *
 * Adds a "Git Push" button to the Node-RED header toolbar,
 * positioned immediately to the right of the Deploy button.
 *
 * To change button position:
 *   - Use .prependTo() to place it on the left side of the toolbar
 *   - Use .appendTo() to place it on the right side of the toolbar
 *   - Call RED.gitPushButton.init() before RED.deploy.init() in red.js
 *     to place it to the LEFT of the Deploy button instead.
 */

RED.gitPushButton = (function() {

    function init() {
        // Create a <li> item and prepend it into the header toolbar.
        // Since deploy.init() runs first, this button will appear
        // immediately to the RIGHT of the Deploy button.
        // Uses the same CSS classes as the Deploy button (red-ui-deploy-button-group,
        // red-ui-deploy-button, red-ui-deploy-button-content) so it looks identical.
        // The explicit style="font-size:14px" matches the .button-group > a rule in header.scss
        // and prevents inheriting the 20px font-size from parent toolbar items.
        $('<li>' +
              '<span class="red-ui-deploy-button-group button-group">' +
                  '<a id="red-ui-header-button-gitpush" class="red-ui-deploy-button" href="#" style="font-size:14px; padding:4px 12px;">' +
                      '<span class="red-ui-deploy-button-content">' +
                          '<span>Git Push</span>' +
                      '</span>' +
                  '</a>' +
              '</span>' +
          '</li>').prependTo(".red-ui-header-toolbar");

        // Wire up click handler — invokes the registered action by name
        $('#red-ui-header-button-gitpush').on('click', function(e) {
            e.preventDefault();
            RED.actions.invoke("core:git-push");
        });

        // Register the action so it can also be triggered via keyboard shortcuts or menus
        RED.actions.add("core:git-push", function() {
            // Read the active tab id and label for the commit message.
            var activeId = RED.workspaces.active();
            var activeFlow = RED.nodes.workspace(activeId);
            var flowLabel = (activeFlow && activeFlow.label) ? activeFlow.label : "flow";
            var commitMessage = "Flow update: " + flowLabel;

            // Branch name is resolved server-side (global env → flow env → fallback).
            // We send the tabId so the server can look up this tab's env vars,
            // and a sanitised fallback in case neither env var is set.
            var fallbackBranch = "flow/" + flowLabel
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, "-")
                .replace(/^-+|-+$/g, "");

            // Disable the button while the operation is in progress
            var $btn = $("#red-ui-header-button-gitpush");
            $btn.addClass("disabled").css("pointer-events", "none");

            // POST /gitpush — server resolves branch via: global env → flow env → fallback
            $.ajax({
                url: "gitpush",
                type: "POST",
                contentType: "application/json",
                data: JSON.stringify({
                    message: commitMessage,
                    tabId: activeId,
                    branch: fallbackBranch
                }),
                success: function(data) {
                    var branch = (data && data.branch) ? data.branch : fallbackBranch;
                    RED.notify("Git push successful: " + commitMessage + " → " + branch, "success");
                },
                error: function(xhr) {
                    var errMsg = "Git push failed";
                    try {
                        var resp = JSON.parse(xhr.responseText);
                        if (resp && resp.error) { errMsg = resp.error; }
                    } catch (e) {}
                    RED.notify(errMsg, "error");
                },
                complete: function() {
                    // Re-enable the button regardless of success or failure
                    $btn.removeClass("disabled").css("pointer-events", "");
                }
            });
        });
    }

    // Expose init() so red.js can call RED.gitPushButton.init()
    return {
        init: init
    };

})();
